const fs=require('fs'),path=require('path');
const origin='https://teruya1229.github.io';
const core=['index.html','moving/index.html','business-cleaning/index.html','aircon/index.html','house-cleaning/index.html','toilet/index.html','reform/index.html','washlet/index.html','lighting/index.html','mi-bcs/aircon-replacement/index.html','mi-bcs/index.html','prices/index.html','cursor-test/index.html','cursor-test/nanjo.html','cursor-test/naha.html','cursor-test/yaese.html','cursor-test/haebaru.html','cursor-test/yonabaru.html','cursor-test/tomigusuku.html','cursor-test/itoman.html','cursor-test/south.html','cursor-test/central.html','cursor-test/urasoe.html','complete-disassembly/index.html'];
const site=new Set(),all=[];function walk(p){for(const entry of fs.readdirSync(p,{withFileTypes:true})){if(entry.name==='.git'||entry.name==='node_modules'||entry.name==='qa'||entry.name==='dist')continue;const abs=path.join(p,entry.name);if(entry.isDirectory())walk(abs);else if(entry.name.endsWith('.html')){const rel=path.relative('.',abs).split(path.sep).join('/');all.push(rel);site.add(rel)}}}walk('.');
function pathnameToPath(u){let p=decodeURI(u.pathname).replace(/^\/+/,'');if(!p||p.endsWith('/'))p+='index.html';else if(!path.posix.extname(p))p+='/index.html';return p}
function urlFor(file){return origin+'/'+(file.endsWith('/index.html')?file.slice(0,-10):file==='index.html'?'':file)}
function anchors(code){const noComments=code.replace(/<!--[\s\S]*?-->/g,'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,'');const list=[];let m;const re=/<a\b[^>]*?\bhref\s*=\s*(["'])([\s\S]*?)\1[^>]*>/gi;while((m=re.exec(noComments))){const closing=noComments.indexOf('</a',re.lastIndex);const raw=noComments.slice(re.lastIndex,closing>-1?closing:re.lastIndex);const label=raw.replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim().slice(0,90);list.push({href:m[2].trim(),label})}return list}
const graph={},broken=[],missingFragments=[],external={};for(const source of all){const code=fs.readFileSync(source,'utf8'),base=urlFor(source),links=anchors(code),dests=[],issues=[];
for(const a of links){let u;try{u=new URL(a.href,base)}catch{continue}if(!/^https?:$/.test(u.protocol))continue;if(u.hostname!=='teruya1229.github.io'){const host=u.hostname;external[host]=(external[host]||0)+1;continue}const target=pathnameToPath(u);dests.push(target);
if(!site.has(target)){const event={source,href:a.href,target,label:a.label};broken.push(event);issues.push(event);continue}
if(u.hash){const fragment=decodeURIComponent(u.hash.slice(1)),destCode=fs.readFileSync(target,'utf8');if(!destCode.includes('id="'+fragment+'"')&&!destCode.includes("id='"+fragment+"'")&&!destCode.includes('name="'+fragment+'"')&&!destCode.includes("name='"+fragment+"'"))missingFragments.push({source,target,fragment,href:a.href});}
}
graph[source]={links:links.length,unique:[...new Set(dests)],localHref:dests.length,internalUnique:[...new Set(dests)].length,issues};}
const incoming={};for(const [from,v] of Object.entries(graph))for(const to of v.unique){if(!incoming[to])incoming[to]=[];incoming[to].push(from);}
const known=core.filter(x=>site.has(x));const nodes=known.map(x=>({path:x,sourceHref:graph[x].links,internalOut:graph[x].internalUnique,incoming:(incoming[x]||[]).length,incomingCore:(incoming[x]||[]).filter(y=>core.includes(y)).length,fromCore:(incoming[x]||[]).filter(y=>core.includes(y)),toCore:graph[x].unique.filter(y=>core.includes(y)&&y!==x)}));
function reachable(start){const seen=new Set([start]),todo=[start];for(let i=0;i<todo.length;i++){for(const t of graph[todo[i]]?.unique||[])if(!seen.has(t)&&site.has(t)){seen.add(t);todo.push(t)}}return [...seen]}
const home=reachable('index.html'),family=reachable('cursor-test/index.html');
const regions=['cursor-test/nanjo.html','cursor-test/naha.html','cursor-test/yaese.html','cursor-test/haebaru.html','cursor-test/yonabaru.html','cursor-test/tomigusuku.html','cursor-test/itoman.html'],south='cursor-test/south.html',central='cursor-test/central.html',urasoe='cursor-test/urasoe.html';
const hub={south:{outRegions:regions.filter(x=>graph[south]?.unique.includes(x)),backRegions:regions.filter(x=>graph[x]?.unique.includes(south))},central:{outUrasoe:graph[central]?.unique.includes(urasoe),backUrasoe:graph[urasoe]?.unique.includes(central)},family:{outSouth:graph['cursor-test/index.html']?.unique.includes(south),outCentral:graph['cursor-test/index.html']?.unique.includes(central),outUrasoe:graph['cursor-test/index.html']?.unique.includes(urasoe)}};
const stats={files:all.length,core:known.length,missingCore:core.filter(x=>!site.has(x)),broken:broken.length,missingFragments:missingFragments.length,allLinks:Object.values(graph).reduce((n,v)=>n+v.links,0),coreUnreachableFromHome:known.filter(x=>!home.includes(x)),coreUnreachableFromFamily:known.filter(x=>!family.includes(x)),hub};
const report={stats,nodes,broken,missingFragments,external,all,graph};
fs.mkdirSync('qa-link-audit-20261119',{recursive:true});fs.writeFileSync('qa-link-audit-20261119/report.json',JSON.stringify(report,null,2));fs.writeFileSync('qa-link-audit-20261119/summary.txt',[JSON.stringify(stats,null,2),'\nBROKEN:\n'+broken.map(x=>JSON.stringify(x)).join('\n'),'\nMISSING_FRAGMENTS:\n'+missingFragments.map(x=>JSON.stringify(x)).join('\n'),'\nCORE GRAPH:\n'+nodes.map(x=>JSON.stringify(x)).join('\n')].join('\n'));
console.log('LP_LINK_AUDIT_COUNTS '+JSON.stringify(stats));console.log('LP_LINK_BROKEN '+JSON.stringify(broken.slice(0,60)));console.log('LP_LINK_FRAGMENTS '+JSON.stringify(missingFragments.slice(0,40)));for(const n of nodes)console.log('LP_LINK_CORE '+JSON.stringify(n));
